  unfold rmalloc_entry, RNEED_LOCKS in *.
  step. carve_frame 48%nat ST. step. step. step. step. step. step.

  step. step. step.
  step. if_cases K0; zify_cond K0. 2:{ exfalso. rewrite ?unsigned_lit in K0 by lia. lia. }
  clear K0.

